/** Derive UI gates from actual +/- native fields on retained vs removed source vertices. */
import fs from'node:fs';import{loadAnny,gunzip}from'../teachers.mjs';
const a=loadAnny(),c=JSON.parse(new TextDecoder().decode(gunzip('kaopu-unified-human-workbench/assets/canonical.json.gz'))),neutral=a.forward({phenotypes:c.referenceAnnyPhenotypes}).restVertices,retained=new Set();for(const[u,v,t]of c.annyRecipes){if(t<1)retained.add(u);if(t>0)retained.add(v);}const rows=[];
for(const label of a.localChangeLabels){let bodyMax=0,headMax=0;for(const amount of[-1,1]){const v=a.forward({phenotypes:c.referenceAnnyPhenotypes,localChanges:{[label]:amount}}).restVertices;for(let i=0;i<a.vertexCount;i++){const d=Math.hypot(v[i*3]-neutral[i*3],v[i*3+1]-neutral[i*3+1],v[i*3+2]-neutral[i*3+2]);if(retained.has(i))bodyMax=Math.max(bodyMax,d);else headMax=Math.max(headMax,d);}}const body=bodyMax>1e-6,head=headMax>1e-6;rows.push({label,bodyMaxMM:bodyMax*1000,removedHeadMaxMM:headMax*1000,bodyResponds:body,headResponds:head,gate:!body&&head?'disabled-head-transfer-pending':body&&head?'body-active-head-partial':body?'body-active':'no-measured-response-review'});}
const out={schema:'anny-local-region-gates/1',reference:c.referenceAnnyPhenotypes,samples:[-1,1],numericalResponseThresholdMetres:1e-6,thresholdPurpose:'Classifies practical source response above float32 forward noise, not an anatomical accuracy tolerance',method:'Actual native rest-shape vertices, before bone reorientation, that contribute to fixed canonical body recipes versus source vertices removed for the GNM head; no label-name inference',rows,disabledLabels:rows.filter(r=>r.gate==='disabled-head-transfer-pending').map(r=>r.label),partiallyMappedLabels:rows.filter(r=>r.gate==='body-active-head-partial').map(r=>r.label)};fs.writeFileSync('research/anny-local-region-gates.json',JSON.stringify(out,null,2));console.log(Object.fromEntries([...new Set(rows.map(r=>r.gate))].map(k=>[k,rows.filter(r=>r.gate===k).length])));
